function activate(context) {
  function hasOpenTabs() {
    for (const group of vscode.window.tabGroups.all) {
      if (group.tabs.length > 0) return true;
    }
    return false;
  }

  function maximizePanel() {
    vscode.commands
      .executeCommand('workbench.action.toggleMaximizedPanel')
      .catch(() => {});
  }

  const folders = vscode.workspace.workspaceFolders;
  if (folders && folders.length > 0) {
    const pattern = new vscode.RelativePattern(
      folders[0],
      '.git/.factory-scm-trigger'
    );
    const watcher = vscode.workspace.createFileSystemWatcher(pattern);
    const refresh = () => {
      vscode.commands.executeCommand('git.refresh').catch(() => {});
    };
    watcher.onDidChange(refresh);
    watcher.onDidCreate(refresh);
    context.subscriptions.push(watcher);
  }

  context.subscriptions.push(
    vscode.window.tabGroups.onDidChangeTabs((event) => {
      if (event.closed.length > 0 && !hasOpenTabs()) {
        maximizePanel();
      }
    })
  );
}

function deactivate() {}

module.exports = { activate, deactivate };
